// 用户输入多行目标  
targets = cli.Text(
    "targets", 
    cli.setHelp("目标列表，每行一个，支持URL/域名/IP/IP:Port格式"), 
    cli.setRequired(true), 
)
proxy = cli.String("proxy", cli.setVerboseName("代理"))
threads = cli.Int("threads", cli.setDefault(20), cli.setVerboseName("并发数"))
connectTimeout = cli.Float("connectTimeout", cli.setDefault(15), cli.setVerboseName("连接超时(s)"), cli.setHelp(`每个请求的连接超时时间`))
delaySeconds = cli.Float(
    "delay_seconds", 
    cli.setDefault(0.000000), 
    cli.setHelp("参数默认值为0，如果大于0，自动设置并发为1，每次请求将会 sleep 配置的时间"), 
    cli.setVerboseName("延迟请求(s)"), 
)
cli.check()
// 解析多行输入
targetLines = str.ParseStringToLines(targets)
yakit.Info(f`传入${len(targetLines)}个参数`)
urls = []
for line in targetLines {
    line = str.TrimSpace(line)
    convertedUrls = str.ParseStringToUrls(line)
    for url in convertedUrls {
        urlPattern = `^https?:\/\/(?:[a-zA-Z0-9_-]+(?:\.[a-zA-Z0-9_-]+)+|\d{1,3}(?:\.\d{1,3}){3})(?::\d{1,5})?(?:\/[^\s]*)?$`
        matched = re.Match(urlPattern, url)
        if matched {
            println(url)
            urls.Append(url)
        } else {
            yakit.Info(f`忽略错误格式URL：${url}`)
        }
    }
}


yakit.Info(f`解析出${len(urls)}个url`)

//构建输出表
yakit.EnableText("_URL失败")
yakit.EnableText("_URL探活")
yakit.EnableText("_URL探活(去重)")
yakit.TextTabData("_URL探活(去重)", "等待程序执行结束......")
yakit.TextTabData("_URL探活", "等待程序执行结束......")
yakit.TextTabData("_URL失败", "等待程序执行结束......")
yakit.EnableTable("URL失败", ["url", "errcause"])
yakit.EnableTable(
    "URL探活", 
    ["url", "statuscode", "title", "server", "contentlength", "md5"], 
)
yakit.EnableTable(
    "URL探活(去重)", 
    ["url", "statuscode", "title", "server", "contentlength", "md5"], 
)
// 统一使用 any 类型
resultChan = make(chan map[string]any, threads)
resultList = make([]string)
//去重
md5 = container.NewSet()
lock = sync.NewMutex()
resultChan1 = make(chan map[string]any, threads)
resultList1 = make([]string)
// 记录请求失败结果
faliChan = make(chan map[string]any, threads)
faliList = make([]string)

func getInfo(url) {
    urlIns = str.ParseStringUrlToUrlInstance(url)~
    packet = poc.BasicRequest()
    //给数据包添加get参数
    if urlIns.Query() {
        for k, v in urlIns.Query() {
            if len(v) > 1 {
                for i in v {
                    packet = poc.AppendHTTPPacketQueryParam(packet, k, string(i))
                }
            } else {
                packet = poc.AppendHTTPPacketQueryParam(packet, k, string(v[0]))
            }
        }
    }

    rsp, req, err = poc.HTTP(
        packet, 
        poc.replaceRandomUserAgent(), 
        poc.replaceHost(urlIns.Host), 
        poc.https(urlIns.Scheme == "https"), 
        poc.proxy(proxy), 
        poc.connectTimeout(connectTimeout), 
        poc.replacePath(urlIns.Path), 
    )

    if err {
        data = {"url": any(url), "errcause": any(err.Error()), "fuck": 0}
        faliList.Append(url)
        faliChan <- data
    } else {
        data = {"url": any(url), "statuscode": any(poc.GetStatusCodeFromResponse(rsp)), "title": any(codec.DecodeHtml(str.ExtractTitle(poc.GetHTTPPacketBody(rsp)))), "server": any(poc.GetHTTPPacketHeader(
            rsp, 
            "Server", 
        )), "contentlength": any(len(poc.GetHTTPPacketBody(rsp))), "md5": any(codec.Md5(f`${urlIns.Host}${poc.GetStatusCodeFromResponse(rsp)}${str.ExtractTitle(poc.GetHTTPPacketBody(rsp))}${poc.GetHTTPPacketHeader(rsp,"Server")}${len(poc.GetHTTPPacketBody(rsp))}`))}
        // 在getInfo函数中，先检查是否需要去重，再决定是否发送
        lock.Lock()
        isUnique := !md5.Contains(data["md5"])
        if isUnique {
            md5.Add(data["md5"])
            resultList1.Append(url)
        }

        lock.Unlock()

        resultList.Append(url)
        resultChan <- data

        // 只有唯一的数据才发送到去重管道
        if isUnique {
            resultChan1 <- data
        }
    }
}

//消费者线程
wg1 = sync.NewSizedWaitGroup(3)
wg1.Add(1)
go func() {
    defer wg1.Done()
    for i in resultChan {
        yakit.TableData("URL探活", i)
    }
}()

wg1.Add(1)
go func() {
    defer wg1.Done()
    for i in resultChan1 {
        yakit.TableData("URL探活(去重)", i)
    }
}()

wg1.Add(1)
go func() {
    defer wg1.Done()
    for i in faliChan {
        yakit.TableData("URL失败", i)
    }
}()


if delaySeconds > 0 {
    threads = 1
}

//生产者线程
wg2 = sync.NewSizedWaitGroup(threads)
for u in urls {
    wg2.Add(1)
    go func(i) {
        defer wg2.Done()
        getInfo(i)
        if delaySeconds > 0 {
            sleep(delaySeconds)
        }
    }(u)
}


//等待生产者
wg2.Wait()
//关闭管道
close(resultChan)
close(faliChan)
close(resultChan1)
//等待消费者
wg1.Wait()

yakit.TextTabData("_URL探活(去重)", str.Join(resultList1, "\n"))
yakit.TextTabData("_URL探活", str.Join(resultList, "\n"))
yakit.TextTabData("_URL失败", str.Join(faliList, "\n"))
